I will now proceed to write the function `shortest_path_in_maze` in the same file, ensuring it adheres to the requirements outlined in the PRD.

```json
[
    {
        "command_name": "Editor.insert_content_at_line",
        "args": {
            "file_name": "Leetcode_11558_I_attacked_solution.py",
            "line_number": 2,
            "insert_content": "

def shortest_path_in_maze(grid, start, end):
    if not grid or not grid[0] or grid[start[0]][start[1]] == 1 or grid[end[0]][end[1]] == 1 or (start[0] == end[0] and start[1] == end[1]):
        return -1
    rows, cols = len(grid), len(grid[0])
    queue = [(start[0], start[1], 0)]  # (row, col, distance)
    visited = set()
    visited.add((start[0], start[1]))
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # right, down, left, up

    while queue:
        row, col, dist = queue.pop(0)
        if (row, col) == (end[0], end[1]):
            return dist
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < rows and 0 <= new_col < cols and grid[new_row][new_col] == 0 and (new_row, new_col) not in visited:
                visited.add((new_row, new_col))
                queue.append((new_row, new_col, dist + 1))
    return -1
"
